(* f32 x rounds a double to the nearest f32. *)
let f32 (x : float) : float = Int32.float_of_bits (Int32.bits_of_float x)

(* Sum a non-empty list the way reduce op=add does:
   start from the first element, add left to right, round to f32 after every add. *)
let sum32 (xs : float list) : float =
  List.fold_left ( +. ) 0.0 xs

